//@ProcessingGroup("role")
@Component("role-projector")
public class RoleProjector extends RoleEntityProjector {
		
	// core constructor
	public RoleProjector(ProjectorRegistry registry,
									RoleRepository repository,
									QueryUpdateEmitter queryUpdateEmitter ) {
        super(registry, repository);
        this.queryUpdateEmitter = queryUpdateEmitter;
    }	

	/*
     * @param	event CreateRoleEvent
     */
    @EventHandler( payloadType=CreateRoleEvent.class )
    public void handle( CreateRoleEvent event) {
	    LOGGER.info("handling CreateRoleEvent - " + event );
	    Role entity = new Role();
            entity.setRoleId( event.getRoleId() );
            entity.setName( event.getName() );
            entity.setResponsibility( event.getResponsibility() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllRole( entity );
    }

    /*
     * @param	event UpdateRoleEvent
     */
    @EventHandler( payloadType=UpdateRoleEvent.class )
    public void handle( UpdateRoleEvent event) {
    	LOGGER.info("handling UpdateRoleEvent - " + event );
    	
	    Role entity = new Role();
            entity.setRoleId( event.getRoleId() );
            entity.setName( event.getName() );
            entity.setResponsibility( event.getResponsibility() );
            entity.setAssignments( event.getAssignments() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindRole( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllRole( entity );        
    }
    
    /*
     * @param	event DeleteRoleEvent
     */
    @EventHandler( payloadType=DeleteRoleEvent.class )
    public void handle( DeleteRoleEvent event) {
    	LOGGER.info("handling DeleteRoleEvent - " + event );
    	
    	// ------------------------------------------
    	// delete delegation
    	// ------------------------------------------
    	Role entity = delete( event.getRoleId() );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllRole( entity );

    }    


    /*
     * @param	event AssignAssignmentsToRoleEvent
     */
    @EventHandler( payloadType=AssignAssignmentsToRoleEvent.class)
    public void handle( AssignAssignmentsToRoleEvent event) {
	    LOGGER.info("handling AssignAssignmentsToRoleEvent - " + event );
	    
	    // ------------------------------------------
    	// delegate to addTo 
    	// ------------------------------------------ 
	    Role entity = addToAssignments(event.getRoleId(), event.getAddTo() );
        
    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindRole( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllRole( entity );
    }
    

/*
 * @param	event RemoveAssignmentsFromRoleEvent
 */
@EventHandler( payloadType=RemoveAssignmentsFromRoleEvent.class)
public void handle( RemoveAssignmentsFromRoleEvent event) {
    LOGGER.info("handling RemoveAssignmentsFromRoleEvent - " + event );

    Role entity = removeFromAssignments(event.getRoleId(), event.getRemoveFrom() );
    
	// ------------------------------------------
	// emit to subscribers that find one
	// ------------------------------------------    	
    emitFindRole( entity );

	// ------------------------------------------
	// emit to subscribers that find all
	// ------------------------------------------    	
    emitFindAllRole( entity );
}



    /**
     * Method to retrieve the Role via an RolePrimaryKey.
     * @param 	id Long
     * @return 	Role
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Role handle( FindRoleQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getRoleId() );
    }
    
    /**
     * Method to retrieve a collection of all Roles
     *
     * @param	query	FindAllRoleQuery 
     * @return 	List<Role> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Role> handle( FindAllRoleQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindRole,
 * but only if the id matches
 *
 * @param		entity	Role
 */
	protected void emitFindRole( Role entity ) {
		LOGGER.info("handling emitFindRole" );
		
	    queryUpdateEmitter.emit(FindRoleQuery.class,
	                            query -> query.getFilter().getRoleId().equals(entity.getRoleId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllRole
	 * 
	 * @param		entity	Role
	 */
	protected void emitFindAllRole( Role entity ) {
		LOGGER.info("handling emitFindAllRole" );
		
	    queryUpdateEmitter.emit(FindAllRoleQuery.class,
	                            query -> true,
	                            entity);
	}

	//--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
	private final QueryUpdateEmitter queryUpdateEmitter;
    private static final Logger LOGGER 	= Logger.getLogger(RoleProjector.class.getName());

}
